//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_error_status(value: *mut bool) -> bool;
  fn put_mode_to_rx(value: *mut open_platform_Data_Model::OperatingMode) -> bool;
  fn put_mode_to_mavlink(value: *mut open_platform_Data_Model::OperatingMode) -> bool;
}

pub fn unsafe_get_error_status() -> bool
{
  unsafe {
    let value: *mut bool = &mut false;
    get_error_status(value);
    return *value;
  }
}

pub fn unsafe_put_mode_to_rx(value: &open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    return put_mode_to_rx(value as *const open_platform_Data_Model::OperatingMode as *mut open_platform_Data_Model::OperatingMode);
  }
}

pub fn unsafe_put_mode_to_mavlink(value: &open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    return put_mode_to_mavlink(value as *const open_platform_Data_Model::OperatingMode as *mut open_platform_Data_Model::OperatingMode);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_error_status: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_mode_to_rx: Mutex<Option<open_platform_Data_Model::OperatingMode>> = Mutex::new(None);
  pub static ref OUT_mode_to_mavlink: Mutex<Option<open_platform_Data_Model::OperatingMode>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_error_status.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_mode_to_rx.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_mode_to_mavlink.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_error_status(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_error_status.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_mode_to_rx(value: *mut open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    *OUT_mode_to_rx.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_mode_to_mavlink(value: *mut open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    *OUT_mode_to_mavlink.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
